import { Formik } from 'formik';
import React, { useRef, useEffect, useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Dimensions,
} from 'react-native';
import useApi from '../../Apis/Services/ApiConfig';
import { useQuery } from '@tanstack/react-query';
import moment from 'moment';
import useEncodedUserData from '../../hooks/useEncodedUserData';
import BottomSheetBase from '../../Helper/BottomSheetBase';
import { getFontSize, SystemOS } from '../../Helper/Helper';
import Skeleton, { getLayout } from '../../Helper/Skeleton';


function leaveStatus(val) {
  if (!val) {
    return 'No Data';
  }
  let rm_value = '';
  let admin_value = '';
  if (val?.rm_id > 0) {
    if (val?.rm_status == 0) {
      rm_value = 'Pending from RM';
    }
    if (val?.rm_status == 2) {
      rm_value = 'Rejected from RM';
    }
    if (val?.rm_status == 1) {
      rm_value = 'Approved from RM';
    }
  }
  if (val?.rm_status == 1 || (val?.rm_status == 0 && val?.rm_id == 0)) {
    if (val?.admin_status == 0) {
      admin_value = 'Pending from Admin';
    }
    if (val?.admin_status == 2) {
      admin_value = 'Rejected from Admin';
    }
    if (val?.admin_status == 1) {
      admin_value = 'Approved from Admin';
    }
  }
  return rm_value + ' ' + admin_value;
  // return val || 'Unknown';
}

const LeaveDetails = ({ leaveId, visible, onClose }) => {
  const { SingleLeaveRequest } = useApi();
  const { userdata } = useEncodedUserData();

  const {
    data: leaveSingleData,
    isLoading: isLeaveSingleLoading,
    isError: isLeaveSingleError,
    isPending,
  } = useQuery({
    queryKey: ['SingleLeaveRequest', userdata],
    queryFn: () =>
      SingleLeaveRequest({ Logid: '', leave_id: leaveId, userData: userdata }),
    enabled: !!userdata,
  });

  const formattedDate = leaveSingleData?.records[0]?.created
    ? moment(leaveSingleData?.records[0]?.created).format('DD MMM YYYY')
    : 'N/A';

  return (
    <>
      <BottomSheetBase visible={visible} onClose={onClose}>
        <Skeleton isLoading={isLeaveSingleLoading || isPending} layout={getLayout({ length: 1, height: 300 })}>
          <View style={{ paddingBottom: 20 }}>
            <View style={{ gap: 10 }}>
              <Text
                style={{
                  fontFamily: 'Poppins-Bold',
                  fontSize: 25,
                  lineHeight: 40,
                  color: '#293646',
                  textTransform: 'capitalize'
                }}>
                {leaveSingleData?.records[0]?.employee_first_name || 'N/A'}{' '}
                {leaveSingleData?.records[0]?.employee_last_name || 'N/A'}
              </Text>
              <View
                style={{
                  flexDirection: 'row',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                }}>
                <Text
                  style={{
                    fontFamily: 'Poppins-Medium',
                    color: '#293646',
                    textAlignVertical: 'center',
                  }}>
                  {leaveSingleData?.records[0]?.leave_type || 'N/A'}
                </Text>
                <Text
                  style={{
                    fontFamily: 'Poppins-Regular',
                    fontSize: 11,
                    textAlign: 'center',
                    textTransform: 'capitalize',
                    backgroundColor:
                      leaveSingleData?.records[0]?.admin_status == 0
                        ? '#FFB22C'
                        : leaveSingleData?.records[0]?.admin_status == 1
                          ? '#5CB338'
                          : '#CA282C',
                    paddingHorizontal: 10,
                    height: 25,
                    borderRadius: 50,
                    color: 'white',
                    lineHeight: SystemOS() ? 18 : 25,
                    textAlignVertical: 'center',
                    marginTop: 0,
                  }}>
                  {leaveStatus(leaveSingleData?.records[0])}
                </Text>
              </View>
              <View style={{ flexDirection: 'row', gap: 10 }}>
                <Text style={{ color: '#293646', fontFamily: 'Poppins-Medium' }}>
                  Applied on:
                </Text>
                <Text style={{ fontFamily: 'Poppins-Regular', color: '#6A7D94' }}>
                  {formattedDate || 'N/A'}
                </Text>
              </View>
              <View
                style={{
                  justifyContent: 'space-between',
                  borderBottomWidth: 1,
                  borderColor: '#6A7D94',
                  paddingBottom: 15,
                  gap: 10,
                }}>
                <View style={{ flexDirection: 'row', gap: 10 }}>
                  <Text
                    style={{ color: '#293646', fontFamily: 'Poppins-Medium' }}>
                    Leave from:
                  </Text>
                  <Text
                    style={{
                      fontFamily: 'Poppins-Regular',
                      flexWrap: 'wrap',
                      flex: 1,
                      color: '#6A7D94',
                    }}>
                    {leaveSingleData?.records[0]?.leave_days
                      ? new Intl.DateTimeFormat('en-GB', {
                        day: '2-digit',
                        month: 'long',
                        year: 'numeric',
                      }).format(
                        new Date(leaveSingleData?.records[0]?.start_date),
                      )
                      : 'N/A'}{' '}
                    -{' '}
                    {leaveSingleData?.records[0]?.leave_days
                      ? new Intl.DateTimeFormat('en-GB', {
                        day: '2-digit',
                        month: 'long',
                        year: 'numeric',
                      }).format(
                        new Date(leaveSingleData?.records[0]?.end_date),
                      )
                      : 'N/A'}
                  </Text>
                </View>
                <View style={{ flexDirection: 'row' }}>
                  <Text
                    style={{ color: '#293646', fontFamily: 'Poppins-Medium' }}>
                    Days:
                  </Text>
                  <Text
                    style={{ fontFamily: 'Poppins-Regular', color: '#6A7D94' }}>
                    {' '}
                    {leaveSingleData?.records[0]?.leave_days || 'N/A'}
                  </Text>
                </View>
              </View>

              <Text
                style={{
                  fontFamily: 'Poppins-Regular',
                  fontStyle: 'italic',
                  color: '#6A7D94',
                  marginTop: 15,
                }}>
                {leaveSingleData?.records[0]?.reason || 'N/A'}
              </Text>
            </View>
          </View>
        </Skeleton>
      </BottomSheetBase>
    </>
  );
};

