import React, { useEffect, useRef, useState } from 'react';
import {
    View,
    StyleSheet,
    Text,
    TouchableOpacity,
    NativeModules,
    NativeEventEmitter,
    findNodeHandle,
    UIManager,
    Platform,
} from 'react-native';
import { requireNativeComponent } from 'react-native';
import { CameraIcon } from '../../../Helper/IconsLoad';
import { getFontSize } from '../../../Helper/Helper';

const FaceCaptureViewNative = requireNativeComponent('FaceCaptureView');

interface FaceCaptureData {
    embedding: number[];
    faceWidth: number;
    faceHeight: number;
    timestamp: string;
    success: boolean;
}

interface FaceCaptureScreenProps {
    onFaceCaptured?: (data: FaceCaptureData) => void;
    autoCapture?: boolean;
    captureDelay?: number;
}

export default function FaceCaptureScreen({
    onFaceCaptured,
    autoCapture = false,
    captureDelay = 1000,
}: FaceCaptureScreenProps) {
    const viewRef = useRef(null);
    const [isCapturing, setIsCapturing] = useState(false);
    const [lastCapture, setLastCapture] = useState<FaceCaptureData | null>(null);
    const [captureCount, setCaptureCount] = useState(0);

    useEffect(() => {
        // Set up event listener for face capture
        const eventEmitter = new NativeEventEmitter(NativeModules.DeviceEventManagerModule);

        const subscription = eventEmitter.addListener('onFaceCaptured', (event: FaceCaptureData) => {

            setLastCapture(event);
            setCaptureCount(prev => prev + 1);

            if (onFaceCaptured) {
                onFaceCaptured(event);
            }
        });

        return () => {
            subscription.remove();
        };
    }, [onFaceCaptured]);

    const sendCommand = (commandName: string, args: any[] = []) => {
        const handle = findNodeHandle(viewRef.current);
        if (handle) {
            UIManager.dispatchViewManagerCommand(
                handle,
                commandName,
                args
            );
        }
    };

    const handleStartCapture = () => {
        setIsCapturing(true);
        sendCommand('startCapture');
    };

    const handleStopCapture = () => {
        setIsCapturing(false);
        sendCommand('stopCapture');
    };

    const handleManualCapture = () => {
        sendCommand('captureFace');
        handleStopCapture();

    };

    const handleSwitchCamera = () => {
        sendCommand('switchCamera');
    };


    const copyEmbeddingToClipboard = () => {
        if (lastCapture) {
            const embeddingStr = JSON.stringify(lastCapture.embedding);
            // You can use Clipboard API here if needed
        }
    };

    return (
        <View style={styles.container}>

            {/* Native Camera View */}
            <FaceCaptureViewNative
                ref={viewRef}
                style={styles.cameraView}
                autoCapture={autoCapture}
                captureDelay={captureDelay}
            />
            <TouchableOpacity style={{ position: 'absolute', width: 50, height: 50, backgroundColor: 'white', borderRadius: 100, justifyContent: 'center', alignItems: 'center', right: 20, top: 20 }} onPress={handleSwitchCamera}>
                <CameraIcon />
            </TouchableOpacity>
            {/* Control Panel */}
            <View style={styles.controlPanel}>
                <View style={styles.buttonRow}>
                    {!isCapturing ? (
                        <TouchableOpacity
                            style={[styles.button, styles.startButton]}
                            onPress={handleStartCapture}
                        >
                            <Text style={styles.buttonText}>Start Capture</Text>
                        </TouchableOpacity>
                    ) : (
                        <TouchableOpacity
                            style={[styles.button, styles.stopButton]}
                            onPress={handleStopCapture}
                        >
                            <Text style={styles.buttonText}>Stop Capture</Text>
                        </TouchableOpacity>
                    )}

                    <TouchableOpacity
                        style={[styles.button, styles.manualButton]}
                        onPress={handleManualCapture}
                        disabled={!isCapturing}
                    >
                        <Text style={styles.buttonText}>Capture Now</Text>
                    </TouchableOpacity>
                </View>

                {/* Capture Info */}
                {/* {lastCapture && (
                    <View style={styles.infoPanel}>
                        <Text style={styles.infoTitle}>Last Capture Info</Text>
                        <Text style={styles.infoText}>
                            Embedding Length: {lastCapture.embedding.length}
                        </Text>
                        <Text style={styles.infoText}>
                            Face Size: {lastCapture.faceWidth}x{lastCapture.faceHeight}
                        </Text>
                        <Text style={styles.infoText}>
                            Total Captures: {captureCount}
                        </Text>
                        <Text style={styles.infoText}>
                            First 5 values: {lastCapture.embedding.slice(0, 5).map(v => v.toFixed(4)).join(', ')}
                        </Text>

                        <TouchableOpacity
                            style={[styles.button, styles.copyButton]}
                            onPress={copyEmbeddingToClipboard}
                        >
                            <Text style={styles.buttonText}>Copy Embedding</Text>
                        </TouchableOpacity>
                    </View>
                )} */}
            </View>
        </View>
    );
}

