import React, { useEffect } from 'react';
import {
  View,
  Text,
  ImageBackground,
  Dimensions,
  StyleSheet,
  TouchableOpacity,
  FlatList,
} from 'react-native';
import backgroundImage from '../../assets/Icon/background.png';
import { SafeAreaProvider, SafeAreaView } from 'react-native-safe-area-context';
import {
  AttendanceIcon,
  CalendarIcon,
  ChatIcon,
  EmployeesIcon,
  ExpenseIcon,
  IdCardIcon,
  LeavesIcon,
  LogoutIcon,
  PayrollIcon,
  PermissionIcon,
  RegisterFaceIcon,
  SettingIcon,
  TeamsIcon,
  TrackLocationIcon,
} from '../Helper/IconsLoad';
import { useAuth } from '../Context/AuthContext';
import { BOTTOM_TAB_HEIGHT, getFontSize, STATUS_BAR_HEIGHT, SystemOS } from '../Helper/Helper';
import ThemedText from '../Helper/ThemedText';

const Dashboard = ({ navigation }) => {
  return (
    <SafeAreaView style={{ flex: 1 }}>
      <ImageBackground
        source={backgroundImage}
        resizeMode="cover"
        style={{ ...StyleSheet.absoluteFillObject, flex: 1, backgroundColor: '#F9F9F9' }}>
        <View style={{ paddingTop: STATUS_BAR_HEIGHT() }}>
          <View
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              justifyContent: 'space-between',
              paddingHorizontal: 20,
            }}>
            <ThemedText size='xl' weight='Medium'>
              Dashboard
            </ThemedText>
            {/* <View style={{ flexDirection: 'row', alignItems: 'center', gap: 5 }}>
                <LogoutIcon />
                <Text style={{ fontFamily: 'Poppins-Medium', fontSize: 15, color: '#CA282C', lineHeight: 15 }}>
                  LOG OUT
                </Text>
              </View> */}
          </View>
          <View
            style={{
              marginTop: 20,
              justifyContent: 'center',
              alignItems: 'center',
              paddingBottom: BOTTOM_TAB_HEIGHT + BOTTOM_TAB_HEIGHT,
            }}>
            <Grid navigation={navigation} />
          </View>
        </View>
      </ImageBackground>
    </SafeAreaView>
  );
};

const Grid = React.memo(({ navigation }) => {
  const { userType, profileData, permissions } = useAuth();
  const HIDE_FACE_RECOGNITION =
    (userType === 'employee' &&
      (profileData?.isFaceRegisterd === true ||
        profileData?.permission?.face_detection !== 1)) ||
    !(userType === 'hr' || userType === 'ceo' || userType === 'admin');

  const data = [
    ...(!permissions?.hide_attendance
      ? [
        {
          id: '1',
          value: 'Attendance',
          icon: <AttendanceIcon color="#CA282C" width={30} height={30} />,
          screenName: 'AttendanceScreen',
          hide: false,
        },
      ]
      : []),

    ...(!permissions?.hide_leaves
      ? [
        {
          id: '2',
          value: 'Leaves',
          icon: <LeavesIcon color="#CA282C" width={30} height={30} />,
          screenName: 'LeaveScreen',
          hide: false,
        },
      ]
      : []),

    ...(!permissions?.hide_team
      ? [
        {
          id: '9',
          value: 'Team',
          icon: <TeamsIcon color="#CA282C" width={30} height={30} />,
          screenName: 'TeamScreen',
          hide: false,
        },
      ]
      : []),

    ...(!HIDE_FACE_RECOGNITION && !permissions?.hide_register_face && SystemOS()
      ? [
        {
          id: '10',
          value: 'Register Faces',
          icon: <RegisterFaceIcon color="#CA282C" width={30} height={30} />,
          screenName: 'FaceRecognitionScreen',
          hide: false,
        },
      ]
      : []),

    ...(!permissions?.hide_payroll
      ? [
        {
          id: '3',
          value: 'Payroll',
          icon: <PayrollIcon color="#CA282C" width={30} height={30} />,
          screenName: 'PayrollScreen',
          hide: false,
        },
      ]
      : []),


    ...(!permissions?.hide_holiday_calendar
      ? [
        {
          id: '6',
          value: 'Holiday Calendar',
          icon: <CalendarIcon color="#CA282C" width={30} height={30} />,
          screenName: 'HolidayScreen',
          hide: false,
        },
      ]
      : []),

    ...(!permissions?.hide_id_card
      ? [
        {
          id: '7',
          value: 'Id Card',
          icon: <IdCardIcon color="#CA282C" width={30} height={30} />,
          screenName: 'VisitingIdScreen',
          hide: false,
        },
      ]
      : []),

    ...(!permissions?.hide_expenses
      ? [
        {
          id: '10',
          value: 'Expenses',
          icon: <ExpenseIcon color="#CA282C" width={30} height={30} />,
          screenName: 'ExpensesScreen',
          hide: false,
        },
      ]
      : []),


    ...(!permissions?.hide_track_employees
      ? [
        {
          id: '8',
          value: 'Track Employees',
          icon: <TrackLocationIcon color="#CA282C" width={30} height={30} />,
          screenName: 'EmployeeLocator',
          hide: false,
        },
      ]
      : []),



    ...(userType === 'admin' ||
      userType === 'ceo' ||
      userType === 'company_admin' ||
      userType === 'hr'
      ? [
        ...(!permissions?.hide_permissions
          ? [
            {
              id: '13',
              value: 'Permission',
              icon: <PermissionIcon color="#CA282C" width={30} height={30} />,
              screenName: 'Permission',
            },
          ]
          : []),
        ...(!permissions?.hide_employees
          ? [
            {
              id: '11',
              value: 'Employees',
              icon: <EmployeesIcon color="#CA282C" width={30} height={30} />,
              screenName: 'Employees',
              hide: false,
            },
          ]
          : []),

        // ...(!permissions?.hide_chat
        //   ? [
        //     {
        //       id: '12',
        //       value: 'Chat',
        //       icon: <ChatIcon color="#CA282C" width={30} height={30} />,
        //       screenName: 'ChatScreen',
        //       hide: false,
        //     },
        //   ]
        //   : []),
      ]
      : []),
  ];

  const screenWidth = Dimensions.get('window').width - 40;
  const numColumns = 2;
  const gap = 5;

  const availableSpace = screenWidth - (numColumns - 1) * gap;
  const itemSize = availableSpace / numColumns;
  const styles = StyleSheet.create({
    itemContainer: {
      width: itemSize,
      height: itemSize,
      backgroundColor: 'white',
      justifyContent: 'center',
      alignItems: 'center',
      gap: 10,
      borderRadius: 8,
      margin: 3,
      borderWidth: 1,
      borderColor: '#E2E2E2',
    },
    item: {
      justifyContent: 'center',
      alignItems: 'center',
      fontSize: 14,
      fontFamily: 'Poppins-Regular',
      color: '#45484D',
      textAlign: 'center',
    },
  });
  return (
    <FlatList
      data={data}
      contentContainerStyle={{ gap, paddingBottom: 20 }}
      showsVerticalScrollIndicator={false}
      columnWrapperStyle={{ gap }}
      nestedScrollEnabled={true}
      getItemLayout={(data, index) => ({ length: 20, offset: 20 * index, index })}
      renderItem={({ item }) => (
        <TouchableOpacity
          onPress={() => {
            navigation.navigate(item.screenName);
          }}
          style={[styles.itemContainer, { display: item.hide ? 'none' : 'flex' }]}>
          <View
            style={{
              backgroundColor: '#FFF2F2',
              height: 63,
              width: 63,
              justifyContent: 'center',
              alignItems: 'center',
              borderRadius: 20,
            }}>
            {item.icon}
          </View>
          <ThemedText size='sm' weight='Medium'>
            {item.value}
          </ThemedText>
        </TouchableOpacity>
      )}
      keyExtractor={item => item.id}
      numColumns={numColumns}
    />
  );
});

export default Dashboard;
